package com.troday.api.entity;
import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="contract_representative_history") public class RepresentativeHistory {
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="contract_id",nullable=false) private Long contractId; @Column(name="room_tenant_id",nullable=false) private Long roomTenantId; @Column(name="name_snapshot",nullable=false) private String nameSnapshot; @Column(name="event_type",nullable=false) private String eventType; @Column(name="started_at") private LocalDateTime startedAt; @Column(name="ended_at") private LocalDateTime endedAt; @Column(name="is_current",nullable=false) private boolean current; @Column(name="recorded_by_id") private Long recordedById; @Column(nullable=false) private String reason; @Column(name="consent_method",nullable=false) private String consentMethod;
 public Long getId(){return id;} public Long getContractId(){return contractId;} public void setContractId(Long v){contractId=v;} public Long getRoomTenantId(){return roomTenantId;} public void setRoomTenantId(Long v){roomTenantId=v;} public String getNameSnapshot(){return nameSnapshot;} public void setNameSnapshot(String v){nameSnapshot=v;} public String getEventType(){return eventType;} public void setEventType(String v){eventType=v;} public LocalDateTime getStartedAt(){return startedAt;} public void setStartedAt(LocalDateTime v){startedAt=v;} public LocalDateTime getEndedAt(){return endedAt;} public void setEndedAt(LocalDateTime v){endedAt=v;} public boolean isCurrent(){return current;} public void setCurrent(boolean v){current=v;} public Long getRecordedById(){return recordedById;} public void setRecordedById(Long v){recordedById=v;} public String getReason(){return reason;} public void setReason(String v){reason=v;} public String getConsentMethod(){return consentMethod;} public void setConsentMethod(String v){consentMethod=v;}
}
